#!/usr/bin/env bash
# Small-amount (1-9 taka) templates for v12, generated by Claude Sonnet with the labelling guideline
# in the prompt (generate_llm_templates.py --focus micro). Language mix roughly follows the training data.
set -euo pipefail
cd "$(dirname "$0")/../.."
PY=${PY:-python}
D=ml/datasets/micro_gen
mkdir -p "$D"
gen() {  # lang batches seed
  "$PY" ml/data/generate_llm_templates.py --lang "$1" --batches "$2" --seed "$3" --per-batch 25 --workers 3 \
    --focus micro --backend claude --model sonnet --out "$D/templates_$1.jsonl" > "$D/gen_$1.log" 2>&1
}
gen banglish 6 31 &
gen bangla 4 32 &
gen mixed 3 33 &
gen english 3 35 &
wait
tail -n1 "$D"/gen_*.log
cat "$D"/templates_*.jsonl | wc -l
